67: #[derive(Debug, Clone, PartialEq, Eq)]
68: pub struct TransitionRecord {
69:     pub from: StateStatus,
70:     pub to: StateStatus,
71:     pub step_number: u32,
72:     pub reason: String,
73: }
74: 
75: impl<S: State, T: State> From<&TransitionProof<S, T>> for TransitionRecord {
76:     fn from(proof: &TransitionProof<S, T>) -> Self {
77:         Self {
78:             from: proof.from_status(),
79:             to: proof.to_status(),
80:             step_number: proof.step_number(),
81:             reason: proof.reason().to_string(),
82:         }
83:     }
84: }
