90:     pub fn new() -> Self { Self { records: Vec::new() } }
91:     pub fn len(&self) -> usize { self.records.len() }
92:     pub fn is_empty(&self) -> bool { self.records.is_empty() }
93:     pub fn records(&self) -> &[TransitionRecord] { &self.records }
94:     pub fn record<S: State, T: State>(&mut self, proof: &TransitionProof<S, T>) {
