37:         let seq = self.sequence.fetch_add(1, Ordering::SeqCst);
38:         self.total_transitions.fetch_add(1, Ordering::SeqCst);
39:         let mut map = self.machine_logs.lock().expect("lock logs");
40:         map.entry(machine_id).or_default().record(proof);
