60:     if should_fail {
61:         let (paused, proof_pause) = running.pause("resource_wait");
62:         registry.record_transition(id, &proof_pause);
63: 
64:         let (failed, proof_abort) = paused.abort("unrecoverable_fault");
65:         registry.record_transition(id, &proof_abort);
66: 
67:         assert_eq!(failed.status(), StateStatus::Failed);
68:         assert!(failed.status().is_terminal());
69:         registry.mark_failed();
70:     } else {
71:         let (paused, proof_pause) = running.pause("throttle_input");
72:         registry.record_transition(id, &proof_pause);
