56: impl<S: State, T: State> TransitionProof<S, T> {
57:     pub fn new(step_number: u32, reason: impl Into<String>) -> Self where S: ValidTransition<T> {
58:         Self { from: PhantomData, to: PhantomData, step_number, reason: reason.into() }
59:     }
60:     #[allow(clippy::wrong_self_convention)]
61:     pub fn from_status(&self) -> StateStatus { S::status() }
62:     pub fn to_status(&self) -> StateStatus { T::status() }
63:     pub const fn step_number(&self) -> u32 { self.step_number }
64:     pub fn reason(&self) -> &str { &self.reason }
65: }
