92:     pub fn is_empty(&self) -> bool { self.records.is_empty() }
93:     pub fn records(&self) -> &[TransitionRecord] { &self.records }
94:     pub fn record<S: State, T: State>(&mut self, proof: &TransitionProof<S, T>) {
95:         self.records.push(TransitionRecord::from(proof));
96:     }
97:     pub fn is_consistent(&self) -> bool {
98:         if self.records.len() <= 1 { return true; }
99:         for window in self.records.windows(2) {
100:             if window[0].to != window[1].from || window[0].step_number >= window[1].step_number {
101:                 return false;
102:             }
103:         }
104:         true
105:     }
