146: impl<S: State> StateMachine<S> {
147:     pub const fn id(&self) -> u64 { self.id }
148:     pub fn payload(&self) -> &str { &self.payload }
149:     pub const fn step_number(&self) -> u32 { self.step_number }
150:     pub fn status(&self) -> StateStatus { S::status() }
151:     pub fn state_name(&self) -> &'static str { S::name() }
152: 
153:     pub fn transition<Next: State>(
154:         self,
155:         reason: impl Into<String>,
156:     ) -> (StateMachine<Next>, TransitionProof<S, Next>)
157:     where
158:         S: ValidTransition<Next>,
159:     {
160:         let next_step = self.step_number + 1;
161:         let proof = TransitionProof::new(next_step, reason);
162:         let next_machine = StateMachine {
